import type {AlertItem, PricewatchResponse, Product, StoreName} from '@/types/pricewatch';
const stores: StoreName[] = ['WELLCOME', 'PARKNSHOP', 'TASTE', 'AEON', 'HKTVMALL'];
const categorySeeds = [['Rice', 'Rice & Noodles'], ['Milk', 'Dairy'], ['Eggs', 'Chilled'], ['Coffee', 'Beverages'], ['Tissue', 'Household'], ['Pasta', 'Pantry']] as const;
function makeSeries(base: number, variance: number) { return Array.from({length: 90}, (_, index) => ({date: new Date(Date.UTC(2026, 2, index + 1)).toISOString().slice(0, 10), price: Number((base + Math.sin(index / 4) * variance + (index % 11 === 0 ? -0.7 : 0)).toFixed(1))})); }
function makeProduct(index: number): Product { const [category, parent] = categorySeeds[index % categorySeeds.length]; const base = 10 + index * 1.8; const prices = stores.map((store, storeIndex) => { const price = Number((base + storeIndex * 0.85 - (storeIndex === index % stores.length ? 1.2 : 0)).toFixed(1)); return {store, price, prevPrice: Number((price + (storeIndex % 2 === 0 ? 0.5 : -0.3)).toFixed(1)), updatedAt: '2026-06-22T08:00:00+08:00', offerText: storeIndex % 2 === 0 ? 'Limited-time member price' : undefined, link: store === 'HKTVMALL' ? 'https://www.hktvmall.com/' : undefined}; }); return {id: `product-${index + 1}`, code: `HK${1000 + index}`, name: `${category} Product ${index + 1}`, brand: ['Topvalu', 'Nescafe', 'Garden', 'Calbee', 'Meadows'][index % 5] ?? 'Brand', category, categoryPath: [parent, category], prices, history: Object.fromEntries(stores.map((store, storeIndex) => [store, makeSeries(base + storeIndex * 0.85, 0.7 + storeIndex * 0.05)])) as Product['history'], offers: index % 2 === 0 ? [{id: `offer-${index}`, title: 'Buy 2 Save More', details: 'Member-only promotion', validUntil: '2026-06-30', store: stores[index % stores.length]}] : [], watched: index % 3 !== 0, shared: index % 5 === 0, lowest90: index % 4 === 0}; }
const alerts: AlertItem[] = [{id: 'alert-1', severity: 'recall', date: '2026-06-20', title: {en: 'Imported snack recall notice', 'zh-Hant': '進口零食回收通告'}, url: 'https://www.cfs.gov.hk/english/press/20260620_12345.html'}, {id: 'alert-2', severity: 'warning', date: '2026-06-18', title: {en: 'Nutrition label discrepancy warning', 'zh-Hant': '營養標籤資料不符警告'}, url: 'https://www.cfs.gov.hk/english/press/20260618_12345.html'}, {id: 'alert-3', severity: 'notice', date: '2026-06-15', title: {en: 'Food safety update for chilled goods', 'zh-Hant': '冷藏食品安全更新'}, url: 'https://www.cfs.gov.hk/english/press/20260615_12345.html'}];
export async function getMockPricewatch(): Promise<PricewatchResponse> { return {fetchedAt: '2026-06-22T08:00:00+08:00', products: Array.from({length: 18}, (_, index) => makeProduct(index)), alerts}; }
